```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string word; // Palabra a buscar
    int count = 0; // Contador de apariciones

    // Pedir palabra a buscar al usuario
    cout << "Introduzca la palabra a buscar: ";
    getline(cin, word);

    // Abrir el archivo para leer línea por línea
    ifstream file("archivo.txt");

    if (!file) {
        cerr << "Error al abrir el archivo." << endl;
        return 1; // Salir con código de error
    }

    string line; // Variable para almacenar línea actual

    while (getline(file, line)) { // Leer línea por línea
        size_t pos = 0; // Posición actual del último carácter encontrado

        while ((pos = line.find(word, pos)) != string::npos) { // Buscar palabra en línea
            count++; // Incrementar contador de apariciones
            pos++; // Avanzar posición de búsqueda al siguiente carácter después de la palabra encontrada
        }
    }

    file.close(); // Cerrar el archivo

    cout << "La palabra \"" << word << "\" aparece " << count << " veces en el archivo." << endl;

    return 0; // Salir con código de éxito
}
```

En este programa, se pide al usuario la palabra a buscar, luego se abre el archivo especificado para leer línea por línea. Para cada línea, se busca la palabra específica utilizando la función `find` de la clase `string`. Si se encuentra la palabra, se incrementa el contador de apariciones y se actualiza la posición de búsqueda para buscar la siguiente aparición en la misma línea. Al finalizar el proceso de lectura, se muestra el resultado al usuario.

